package io.knowledgebrain.gateway;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
class GitHubWorkProxyTest {
 GatewayProxyTest f;String id="019a0000-0000-7000-8000-000000000001",path="/api/spaces/"+id+"/github/repositories/"+id+"/work-items";
 @BeforeEach void setup()throws Exception{f=new GatewayProxyTest();f.prepare();}@AfterEach void clean(){f.stop();}
 @Test void methodsAndTypedPathsStayExact(){for(String p:new String[]{path,path+"/"+id,path+"/"+id+"/revisions",path+"/ISSUE/sync-state",path+"/PULL_REQUEST/syncs"})assertEquals("integration",GatewayRoute.select("GET",p).service());assertEquals("integration",GatewayRoute.select("POST",path+"/ISSUE/sync").service());for(String method:new String[]{"PUT","DELETE","PATCH"})assertNull(GatewayRoute.select(method,path+"/"+id));assertNull(GatewayRoute.select("POST",path));assertNull(GatewayRoute.select("GET",path+"/UNKNOWN/sync-state"));assertNull(GatewayRoute.select("GET",path+"/ISSUE/sync"));}
 @Test void strictBoundedCatalogHistoryAndBodyGuardsRunBeforeTransport()throws Exception{var good=f.request("GET",path);good.setQueryString("kind=ISSUE&state=OPEN&limit=20&after="+id);assertEquals(200,f.gateway.proxy(good).getStatusCode().value());for(String q:java.util.List.of("kind=COMMIT","state=RETIRED","state=OPEN&state=CLOSED","limit=101","after=bad","before=1","actorId="+id)){var request=f.request("GET",path);request.setQueryString(q);assertThrows(ResponseStatusException.class,()->f.gateway.proxy(request));}var body=f.request("GET",path);body.setContent("{}".getBytes());assertThrows(ResponseStatusException.class,()->f.gateway.proxy(body));var history=f.request("GET",path+"/"+id+"/revisions");history.setQueryString("limit=11");assertThrows(ResponseStatusException.class,()->f.gateway.proxy(history));assertEquals(1,f.requests.get());}
 @Test void workSyncForwardsOnlySingletonOpaqueKeyAndStrongCas()throws Exception{var request=f.request("POST",path+"/ISSUE/sync");request.addHeader("Origin","https://localhost:8443");request.setContentType("application/json");request.setContent("{}".getBytes());request.addHeader("If-Match","\"ghw0\"");assertThrows(ResponseStatusException.class,()->f.gateway.proxy(request));request.addHeader("Idempotency-Key","a".repeat(32));assertEquals(200,f.gateway.proxy(request).getStatusCode().value());assertEquals("a".repeat(32),f.headers.get().getFirst("Idempotency-Key"));assertEquals("\"ghw0\"",f.headers.get().getFirst("If-Match"));assertFalse(f.headers.get().containsKey("Authorization"));}
}
